import csv
import sys
import math

def clean_float(s):
    if not s or s == "":
        return None
    try:
        # Remove surrounding quotes if any (csv reader usually handles this, but just in case)
        s = s.strip().strip('"').strip("'")
        # Replace comma with dot
        s = s.replace(',', '.')
        return float(s)
    except ValueError:
        return None

def analyze():
    filepath = '/root/environment/data/ckd_lab_data.csv'

    # Columns to check for range issues
    check_cols = [
        'Serum_Creatinine', 'Hemoglobin', 'Albumin_Serum', 'Total_Protein', 
        'Glucose', 'Serum_Calcium', 'Phosphorus', 'Potassium', 'Sodium',
        'Total_Cholesterol', 'Triglycerides', 'Uric_Acid', 'Bilirubin' # Bilirubin might be 'Total_Bilirubin'
    ]

    data_values = {col: [] for col in check_cols}

    try:
        with open(filepath, 'r') as f:
            reader = csv.DictReader(f)
            total_rows = 0
            valid_rows = 0

            for row in reader:
                total_rows += 1

                # Check for missing values in ANY column (as per requirement to drop them eventually)
                # But for analysis, we might want to look at all available values for specific columns
                # to get better range estimates.

                for col in check_cols:
                    if col in row:
                        val = clean_float(row[col])
                        if val is not None:
                            data_values[col].append(val)
                    elif col == 'Bilirubin' and 'Total_Bilirubin' in row:
                         val = clean_float(row['Total_Bilirubin'])
                         if val is not None:
                             data_values['Total_Bilirubin'].append(val) # Store in correct key if found


        print(f"Total rows scanned: {total_rows}")

        for col in check_cols:
            vals = data_values.get(col, [])
            if col == 'Bilirubin': 
                vals = data_values.get('Total_Bilirubin', [])
                col = 'Total_Bilirubin'

            if not vals:
                print(f"{col}: No data found")
                continue

            vals.sort()
            _min = vals[0]
            _max = vals[-1]
            _med = vals[len(vals)//2]

            print(f"--- {col} ---")
            print(f"Min: {_min}")
            print(f"Max: {_max}")
            print(f"Median: {_med}")
            print(f"Sample low: {vals[:5]}")
            print(f"Sample high: {vals[-5:]}")
            print("")

    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    analyze()

