import csv
import sys

def clean_float(s):
    if not s or s.strip() == "":
        return None
    try:
        s = s.strip().strip('"').strip("'")
        s = s.replace(',', '.')
        return float(s)
    except ValueError:
        return None

def harmonize():
    input_path = '/root/environment/data/ckd_lab_data.csv'
    output_path = '/root/ckd_lab_data_harmonized.csv'

    # Rules: (Column, threshold, operator, factor)
    # operator: '*' or '/'
    # condition: '>' or '<' relative to threshold
    rules = [
        ('Serum_Creatinine', 40, '>', '/', 88.4),
        ('Hemoglobin', 25, '>', '/', 10.0),
        ('Hemoglobin', 2.8, '<', '*', 6.45),
        ('Albumin_Serum', 10, '>', '/', 10.0),
        ('Total_Protein', 15, '>', '/', 10.0),
        ('Glucose', 25, '<', '*', 18.015),
        ('Serum_Calcium', 4.5, '<', '*', 4.0),
        ('Phosphorus', 2.0, '<', '*', 3.1),
        ('Total_Cholesterol', 15, '<', '*', 38.67),
        ('Triglycerides', 10, '<', '*', 88.57),
        ('Uric_Acid', 30, '>', '/', 59.48),
        ('Total_Bilirubin', 5, '>', '/', 17.1)
    ]

    # Map column names to rules for faster lookup
    rule_map = {}
    for r in rules:
        col = r[0]
        if col not in rule_map:
            rule_map[col] = []
        rule_map[col].append(r)

    rows = []
    headers = []

    try:
        with open(input_path, 'r') as f:
            reader = csv.DictReader(f)
            headers = reader.fieldnames

            for row in reader:
                clean_row = {}
                is_valid = True

                for col in headers:
                    if col == 'patient_id':
                        clean_row[col] = row[col] # Keep ID as is (or int)
                        continue

                    val = clean_float(row[col])
                    if val is None:
                        is_valid = False
                        break
                    clean_row[col] = val

                if is_valid:
                    rows.append(clean_row)

        print(f"Loaded {len(rows)} valid rows.")

        # Apply Harmonization
        harmonized_rows = []
        for row in rows:
            new_row = row.copy()
            for col, rules_list in rule_map.items():
                if col in new_row:
                    val = new_row[col]
                    # Apply rules sequentially (though usually only one triggers)
                    # Note: If multiple rules apply (e.g. ranges), order matters?
                    # My rules are mostly mutually exclusive (low vs high).

                    for rule in rules_list:
                        _, threshold, condition, operator, factor = rule

                        if condition == '>' and val > threshold:
                            if operator == '/':
                                val = val / factor
                            else:
                                val = val * factor
                        elif condition == '<' and val < threshold:
                            if operator == '/':
                                val = val / factor
                            else:
                                val = val * factor

                    new_row[col] = val
            harmonized_rows.append(new_row)

        # Write Output
        with open(output_path, 'w', newline='') as f:
            writer = csv.DictWriter(f, fieldnames=headers)
            writer.writeheader()

            for row in harmonized_rows:
                formatted_row = {}
                for col in headers:
                    if col == 'patient_id':
                        formatted_row[col] = row[col]
                    else:
                        # Format to 2 decimal places
                        formatted_row[col] = "{:.2f}".format(row[col])
                writer.writerow(formatted_row)

        print(f"Successfully wrote {len(harmonized_rows)} rows to {output_path}")

    except Exception as e:
        print(f"Error: {e}")
        import traceback
        traceback.print_exc()

if __name__ == "__main__":
    harmonize()

